 rooftop:{base:'#353e4d',tile:'#424b59',line:'#596475',accent:'#e8ac67',light:'#f1c6aa',dark:.18},
 floodgate:{base:'#294b50',tile:'#36575b',line:'#527a77',accent:'#b4d6bb',light:'#99dfce',dark:.16},
