 server:{base:'#223740',tile:'#2c4550',line:'#456370',accent:'#65d9e2',light:'#a6ebf3',dark:.25},
 residential:{base:'#434a43',tile:'#53594e',line:'#747a65',accent:'#e4b978',light:'#ecd5b2',dark:.12},
 quarry:{base:'#655245',tile:'#74604d',line:'#947e5f',accent:'#e4c287',light:'#ffe0b4',dark:.1},
 power:{base:'#3e484b',tile:'#4c5556',line:'#6b7775',accent:'#e4d469',light:'#dfeebf',dark:.19},
 museum:{base:'#615d56',tile:'#736d63',line:'#968e7e',accent:'#e2c995',light:'#f8e6c1',dark:.1},
